<script>
    // 获取DOM元素
    const slider = document.getElementById('xSlider');
    const dragGroup = document.getElementById('dragGroup');
    const pointX = document.getElementById('pointX');
    const labelX = document.getElementById('labelX');
    const hotspot = document.getElementById('hotspot');
    const pathToA = document.getElementById('pathToA');
    const pathToB = document.getElementById('pathToB');
    const labelToA = document.getElementById('labelToA');
    const labelToB = document.getElementById('labelToB');
    const statusTip = document.getElementById('statusTip');
    const svg = document.getElementById('mathSvg');

    // 公式数值元素
    const valXSpans = document.querySelectorAll('.val-x');
    const valDa = document.querySelector('.val-da');
    const valDb = document.querySelector('.val-db');
    const valSum = document.querySelector('.val-sum');

    // 数轴物理映射：[-3, 3] 映射到 [100, 700] 像素区间
    // 比例尺：1单位 = 100像素。原点 0 在 400px 处。
    const scale = 100;
    const originX = 400;

    function valToPx(val) {
        return originX + val * scale;
    }

    function pxToVal(px) {
        return (px - originX) / scale;
    }

    // 更新视图
    function update(xVal) {
        // 限制范围
        xVal = Math.max(-2.8, Math.min(2.8, xVal));

        // 更新滑块
        slider.value = xVal;

        // 计算物理坐标
        const cx = valToPx(xVal);
        const cy = 100;

        // 移动动点 x
        pointX.setAttribute('cx', cx);
        labelX.setAttribute('x', cx);
        hotspot.setAttribute('cx', cx);

        // 计算距离
        const distA = Math.abs(xVal - (-1));
        const distB = Math.abs(xVal - 1);
        const sum = distA + distB;

        // 渲染距离线段 (用二次贝塞尔曲线做成不同高度的拱桥，避免重叠)
        const pxA = valToPx(-1);
        const pxB = valToPx(1);

        // d2: x 到 A(-1) 的线段 (橙色)
        // 弧度高度随距离拉伸
        const hA = 100 - Math.min(40, distA * 15);
        pathToA.setAttribute('d', `M ${pxA},100 Q ${(pxA + cx)/2},${hA} ${cx},100`);
        labelToA.setAttribute('x', (pxA + cx)/2);
        labelToA.setAttribute('y', hA - 8);
        labelToA.textContent = `|x - (-1)| = ${distA.toFixed(2)}`;

        // d1: x 到 B(1) 的线段 (绿色)
        const hB = 100 - Math.min(40, distB * 15) - 15; // 稍微错开高度
        pathToB.setAttribute('d', `M ${pxB},100 Q ${(pxB + cx)/2},${hB} ${cx},100`);
        labelToB.setAttribute('x', (pxB + cx)/2);
        labelToB.setAttribute('y', hB - 8);
        labelToB.textContent = `|x - 1| = ${distB.toFixed(2)}`;

        // 更新公式数值
        valXSpans.forEach(span => span.textContent = xVal.toFixed(2));
        valDa.textContent = distA.toFixed(2);
        valDb.textContent = distB.toFixed(2);
        valSum.textContent = sum.toFixed(2);

        // 状态提示与高亮
        if (xVal >= -1 && xVal <= 1) {
            statusTip.textContent = "★ 此时 x 在 [-1, 1] 之间，距离之和取得最小值 2！";
            statusTip.className = "status-tip min-reached";
            valSum.style.background = "#22c55e";
            valSum.style.color = "#fff";
        } else {
            statusTip.textContent = "拖动点 x 进入 [-1, 1] 区间看看会发生什么？";
            statusTip.className = "status-tip";
            valSum.style.background = "#f3e8ff";
            valSum.style.color = "#7c3aed";
        }
    }

    // 滑块事件
    slider.addEventListener('input', (e) => {
        update(parseFloat(e.target.value));
    });

    // 预设按钮事件
    document.querySelectorAll('.preset-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const val = parseFloat(btn.getAttribute('data-val'));
            // 平滑过渡效果
            let current = parseFloat(slider.value);
            const step = (val - current) / 10;
            let count = 0;
            function animate() {
                if (count < 10) {
                    current += step;
                    update(current);
                    count++;
                    requestAnimationFrame(animate);
                } else {
                    update(val);
                }
            }
            animate();
        });
    });

    // SVG 拖拽交互实现
    let isDragging = false;

    function getMouseX(e) {
        const rect = svg.getBoundingClientRect();
        // 考虑 SVG viewBox 的缩放
        const clientX = e.touches ? e.touches[0].clientX : e.clientX;
        return (clientX - rect.left) * (800 / rect.width);
    }

    dragGroup.addEventListener('mousedown', (e) => {
        isDragging = true;
        document.body.style.cursor = 'grabbing';
    });

    window.addEventListener('mousemove', (e) => {
        if (!isDragging) return;
        const mouseX = getMouseX(e);
        const xVal = pxToVal(mouseX);
        update(xVal);
    });

    window.addEventListener('mouseup', () => {
        if (isDragging) {
            isDragging = false;
            document.body.style.cursor = 'default';
        }
    });

    // 移动端触摸支持
    dragGroup.addEventListener('touchstart', (e) => {
        isDragging = true;
        e.preventDefault();
    });

    window.addEventListener('touchmove', (e) => {
        if (!isDragging) return;
        const mouseX = getMouseX(e);
        const xVal = pxToVal(mouseX);
        update(xVal);
    });

    window.addEventListener('touchend', () => {
        isDragging = false;
    });

    // 初始化
    update(0);
</script>

</body>
