<script>
    // 数据定义
    const config = [
        {
            condText: "x < -1",
            correct1: "negative", // x-1 < 0
            correct2: "negative", // x+1 < 0
            expr1: "-(x - 1)",
            expr2: "-(x + 1)",
            simplified: "y = -(x - 1) - (x + 1) = -2x"
        },
        {
            condText: "-1 ≤ x ≤ 1",
            correct1: "negative", // x-1 <= 0
            correct2: "positive", // x+1 >= 0
            expr1: "-(x - 1)",
            expr2: "x + 1",
            simplified: "y = -(x - 1) + (x + 1) = 2"
        },
        {
            condText: "x > 1",
            correct1: "positive", // x-1 > 0
            correct2: "positive", // x+1 > 0
            expr1: "x - 1",
            expr2: "x + 1",
            simplified: "y = (x - 1) + (x + 1) = 2x"
        }
    ];

    let currentIdx = null;
    // 记录每个区间的通关状态
    let completed = [false, false, false];

    // DOM 元素获取
    const regions = [
        document.getElementById('region-0'),
        document.getElementById('region-1'),
        document.getElementById('region-2')
    ];
    const buttons = [
        document.getElementById('btn-0'),
        document.getElementById('btn-1'),
        document.getElementById('btn-2')
    ];
    const branches = [
        document.getElementById('branch-0'),
        document.getElementById('branch-1'),
        document.getElementById('branch-2')
    ];

    const placeholderText = document.getElementById('placeholder-text');
    const interactiveFormula = document.getElementById('interactive-formula');
    const condDisplay = document.getElementById('cond-display');
    const select1 = document.getElementById('select-1');
    const select2 = document.getElementById('select-2');
    const expr1Res = document.getElementById('expr-1-res');
    const expr2Res = document.getElementById('expr-2-res');
    const finalStepExpr = document.getElementById('final-step-expr');
    const formulaTitle = document.getElementById('formula-title');

    // 初始化事件监听
    regions.forEach((reg, idx) => {
        reg.addEventListener('click', () => selectInterval(idx));
        // 悬停效果
        reg.addEventListener('mouseenter', () => {
            if (currentIdx !== idx) reg.style.fill = getHoverColor(idx);
        });
        reg.addEventListener('mouseleave', () => {
            if (currentIdx !== idx) reg.style.fill = getNormalColor(idx);
        });
    });

    buttons.forEach((btn, idx) => {
        btn.addEventListener('click', () => selectInterval(idx));
    });

    select1.addEventListener('change', checkAnswers);
    select2.addEventListener('change', checkAnswers);

    // 颜色辅助函数
    function getNormalColor(idx) {
        if (idx === 0) return "rgba(231, 76, 60, 0.08)";
        if (idx === 1) return "rgba(243, 156, 18, 0.08)";
        return "rgba(46, 204, 113, 0.08)";
    }
    function getHoverColor(idx) {
        if (idx === 0) return "rgba(231, 76, 60, 0.18)";
        if (idx === 1) return "rgba(243, 156, 18, 0.18)";
        return "rgba(46, 204, 113, 0.18)";
    }
    function getActiveColor(idx) {
        if (idx === 0) return "rgba(231, 76, 60, 0.3)";
        if (idx === 1) return "rgba(243, 156, 18, 0.3)";
        return "rgba(46, 204, 113, 0.3)";
    }
    function getStrokeColor(idx) {
        if (idx === 0) return "#e74c3c";
        if (idx === 1) return "#f39c12";
        return "#2ecc71";
    }

    // 切换区间选择
    function selectInterval(idx) {
        currentIdx = idx;

        // 更新数轴和按钮状态
        regions.forEach((reg, i) => {
            if (i === idx) {
                reg.style.fill = getActiveColor(i);
                reg.style.stroke = getStrokeColor(i);
            } else {
                reg.style.fill = getNormalColor(i);
                reg.style.stroke = "transparent";
            }
        });

        buttons.forEach((btn, i) => {
            btn.className = "interval-btn";
            if (i === idx) {
                btn.classList.add(`active-${idx}`);
            }
        });

        // 展现推导面板
        placeholderText.style.display = 'none';
        interactiveFormula.style.display = 'block';
        formulaTitle.textContent = `第二步：推导区间 ${idx + 1} 的解析式`;
        condDisplay.textContent = config[idx].condText;

        // 重置下拉框和推导结果
        select1.value = "";
        select2.value = "";
        select1.className = "";
        select2.className = "";
        expr1Res.textContent = "?";
        expr2Res.textContent = "?";
        finalStepExpr.textContent = "y = ( ? ) + ( ? ) = ?";
        finalStepExpr.style.color = "#2c3e50";
    }

    // 检查用户选择
    function checkAnswers() {
        if (currentIdx === null) return;

        const currentConfig = config[currentIdx];
        const val1 = select1.value;
        const val2 = select2.value;

        // 判定第一个绝对值
        if (val1) {
            if (val1 === currentConfig.correct1) {
                select1.className = "correct";
                expr1Res.textContent = currentConfig.expr1;
                expr1Res.style.color = "#2ecc71";
            } else {
                select1.className = "wrong";
                expr1Res.textContent = "?";
                expr1Res.style.color = "#e74c3c";
            }
        }

