<script>
    // 获取DOM元素
    const slider = document.getElementById('a-slider');
    const aValueText = document.getElementById('a-value');
    const lineA = document.getElementById('line-a');
    const labelA = document.getElementById('label-a');
    const intersect1 = document.getElementById('intersection-1');
    const intersect2 = document.getElementById('intersection-2');
    const statusText = document.getElementById('status-text');

    // 坐标映射函数
    // y 值的数学坐标转 SVG 像素坐标
    // y_svg = 330 - y_math * 40
    function mathToSvgY(y) {
        return 330 - y * 40;
    }

    // x 值的数学坐标转 SVG 像素坐标
    // x_svg = 250 + x_math * 40
    function mathToSvgX(x) {
        return 250 + x * 40;
    }

    // 更新可视化状态
    function update(a) {
        // 1. 更新数值文本
        aValueText.textContent = a.toFixed(1);

        // 2. 更新水平线 y = a 的位置
        const svgY = mathToSvgY(a);
        lineA.setAttribute('y1', svgY);
        lineA.setAttribute('y2', svgY);

        // 标签位置微调，防止超出边界
        labelA.setAttribute('y', a > 5.5 ? svgY + 18 : svgY - 8);
        labelA.textContent = `y = ${a.toFixed(1)}`;

        // 3. 计算交点并更新显示
        if (a < 2) {
            // 无交点
            intersect1.style.display = 'none';
            intersect2.style.display = 'none';
            statusText.innerHTML = '当前交点个数：<span class="badge badge-zero">0 个</span> (方程无解)';
        } 
        else if (Math.abs(a - 2) < 0.001) {
            // a = 2，无数个交点 (重合线段)
            // 在端点处显示两个高亮圈，并提示无数个
            intersect1.style.display = 'block';
            intersect2.style.display = 'block';
            intersect1.setAttribute('cx', mathToSvgX(-1));
            intersect1.setAttribute('cy', mathToSvgY(2));
            intersect2.setAttribute('cx', mathToSvgX(1));
            intersect2.setAttribute('cy', mathToSvgY(2));
            statusText.innerHTML = '当前交点个数：<span class="badge badge-infinite">无数个</span> (重合线段)';
        } 
        else {
            // a > 2，两个交点
            // 根据 y = 2x (x > 1) => x = a/2
            // 根据 y = -2x (x < -1) => x = -a/2
            const x1 = -a / 2;
            const x2 = a / 2;

            intersect1.style.display = 'block';
            intersect2.style.display = 'block';

            intersect1.setAttribute('cx', mathToSvgX(x1));
            intersect1.setAttribute('cy', svgY);
            intersect2.setAttribute('cx', mathToSvgX(x2));
            intersect2.setAttribute('cy', svgY);

            statusText.innerHTML = `当前交点个数：<span class="badge badge-two">2 个</span> (x₁ = ${x1.toFixed(2)}, x₂ = ${x2.toFixed(2)})`;
        }
    }

    // 绑定滑动事件
    slider.addEventListener('input', (e) => {
        const a = parseFloat(e.target.value);
        update(a);
    });

    // 初始化
    update(2.0);
</script>

