<script>
    // 获取DOM元素
    const slider = document.getElementById('slider-a');
    const valA = document.getElementById('val-a');
    const lineA = document.getElementById('line-a');
    const labelA = document.getElementById('label-a');
    const valleyHighlight = document.getElementById('valley-highlight');
    const lens = document.getElementById('lens');
    const pointsGroup = document.getElementById('intersection-points');

    const btnHigh = document.getElementById('btn-high');
    const btnLimit = document.getElementById('btn-limit');
    const btnLow = document.getElementById('btn-low');

    // 坐标映射常量 (X_px = 260 + x * 50, Y_px = 310 - y * 50)
    const xToPx = x => 260 + x * 50;
    const yToPx = y => 310 - y * 50;
    const pxToX = px => (px - 260) / 50;

    // 更新视图主函数
    function updateView(a) {
        // 1. 更新滑块和数值显示
        slider.value = a;
        valA.textContent = a.toFixed(1);

        // 2. 更新水平直线位置
        const yPx = yToPx(a);
        lineA.setAttribute('y1', yPx);
        lineA.setAttribute('y2', yPx);

        // 更新直线标签位置
        labelA.setAttribute('y', yPx - 10);
        labelA.textContent = `y = ${a.toFixed(1)}`;

        // 3. 临界状态处理 (a = 2)
        if (Math.abs(a - 2.0) < 0.05) {
            valleyHighlight.style.display = 'block';
            lens.style.display = 'flex';
            drawIntersectionPoints(a, true);
        } else {
            valleyHighlight.style.display = 'none';
            lens.style.display = 'none';
            drawIntersectionPoints(a, false);
        }

        // 4. 更新按钮激活状态
        btnHigh.classList.remove('active');
        btnLimit.classList.remove('active');
        btnLow.classList.remove('active');
        if (Math.abs(a - 3.5) < 0.1) btnHigh.classList.add('active');
        else if (Math.abs(a - 2.0) < 0.1) btnLimit.classList.add('active');
        else if (Math.abs(a - 1.2) < 0.1) btnLow.classList.add('active');
    }

    // 绘制交点
    function drawIntersectionPoints(a, isLimit) {
        pointsGroup.innerHTML = ''; // 清空旧交点

        if (isLimit) {
            // 临界状态下，在 [-1, 1] 区间内绘制多个交点示意“无数个解”
            for (let x = -1; x <= 1; x += 0.4) {
                createPoint(xToPx(x), yToPx(2), '#e6a23c');
            }
        } else if (a > 2) {
            // a > 2 时有两个交点
            // 方程: x - 1 + x + 1 = a => 2x = a => x = a/2 (在 x >= 1 侧)
            // 另一侧 x = -a/2
            const x1 = a / 2;
            const x2 = -a / 2;
            createPoint(xToPx(x1), yToPx(a), '#f56c6c');
            createPoint(xToPx(x2), yToPx(a), '#f56c6c');
        }
        // a < 2 时无交点，不绘制
    }

    // 创建单个SVG圆点
    function createPoint(cx, cy, color) {
        const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circle.setAttribute('cx', cx);
        circle.setAttribute('cy', cy);
        circle.setAttribute('r', '6');
        circle.setAttribute('fill', color);
        circle.setAttribute('stroke', '#fff');
        circle.setAttribute('stroke-width', '1.5');
        pointsGroup.appendChild(circle);
    }

    // 绑定滑块事件
    slider.addEventListener('input', (e) => {
        updateView(parseFloat(e.target.value));
    });

    // 绑定预设按钮事件
    btnHigh.addEventListener('click', () => updateView(3.5));
    btnLimit.addEventListener('click', () => updateView(2.0));
    btnLow.addEventListener('click', () => updateView(1.2));

    // 初始化默认状态
    updateView(2.0);
</script>
