<body>

<div id="app-container">
    <!-- 头部 -->
    <header>
        <h1>分类讨论思维构建：决策树表达</h1>
        <span class="tag">高一数学 · 函数与方程</span>
    </header>

    <!-- 主体 -->
    <div class="main-content">
        <!-- 左侧：决策树 -->
        <div class="left-panel">
            <div class="panel-title">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2v8m0 4v8m-8-6h16"/></svg>
                拖拽卡片构建决策树
            </div>
            <div class="tree-container" id="tree-container">
                <!-- SVG 连线 -->
                <svg class="tree-svg" id="tree-svg">
                    <!-- 动态生成连线 -->
                </svg>

                <!-- 根节点 -->
                <div class="tree-node root-node">输入参数 a</div>

                <!-- 条件槽 -->
                <div class="tree-node drop-zone cond-zone-1" data-type="cond" data-target="a < 2" id="slot-cond-1">放入条件</div>
                <div class="tree-node drop-zone cond-zone-2" data-type="cond" data-target="a = 2" id="slot-cond-2">放入条件</div>
                <div class="tree-node drop-zone cond-zone-3" data-type="cond" data-target="a > 2" id="slot-cond-3">放入条件</div>

                <!-- 结果槽 -->
                <div class="tree-node drop-zone res-zone-1" data-type="res" data-target="0个解" id="slot-res-1">放入结果</div>
                <div class="tree-node drop-zone res-zone-2" data-type="res" data-target="2个解" id="slot-res-2">放入结果</div>
                <div class="tree-node drop-zone res-zone-3" data-type="res" data-target="无数个解" id="slot-res-3">放入结果</div>
            </div>
        </div>

        <!-- 右侧：卡片与验证 -->
        <div class="right-panel">
            <!-- 卡片备选区 -->
            <div class="card-deck">
                <div class="panel-title">候选分类卡片</div>
                <div class="card-container" id="card-container">
                    <div class="drag-card type-cond" draggable="true" data-val="a < 2">a &lt; 2</div>
                    <div class="drag-card type-cond" draggable="true" data-val="a = 2">a = 2</div>
                    <div class="drag-card type-cond" draggable="true" data-val="a > 2">a &gt; 2</div>
                    <div class="drag-card type-res" draggable="true" data-val="0个解">0个解</div>
                    <div class="drag-card type-res" draggable="true" data-val="2个解">2个解</div>
                    <div class="drag-card type-res" draggable="true" data-val="无数个解">无数个解</div>
                </div>
            </div>

            <!-- 验证微型图像区 -->
            <div class="verify-panel">
                <div class="panel-title">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4m0-4h.01"/></svg>
                    动态数形结合验证
                </div>
                <div class="verify-control">
                    <span style="font-size: 13px; font-weight: bold; color: #475569;">参数 a:</span>
                    <input type="range" id="param-a-slider" min="0" max="4" step="0.1" value="1">
                    <span id="param-a-val" style="font-size: 13px; font-weight: bold; color: #2563eb; width: 30px;">1.0</span>
                </div>
                <div class="verify-canvas-container">
                    <canvas id="verify-canvas"></canvas>
                </div>
            </div>
        </div>
    </div>

    <!-- 底部 -->
    <footer>
        <div class="tip-box" id="tip-box">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" stroke-width="2"><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3m.08 4h.01"/></svg>
            <span>提示：请将右侧的条件和结果卡片拖拽到左侧对应的决策树分支中。</span>
        </div>
        <button class="btn-reset" id="btn-reset">重置决策树</button>
    </footer>
</div>

<script>
    // 1. 拖拽交互逻辑
    const cards = document.querySelectorAll('.drag-card');
    const dropZones = document.querySelectorAll('.drop-zone');
    const tipBox = document.getElementById('tip-box');
    let draggedCard = null;

    cards.forEach(card => {
        card.addEventListener('dragstart', () => {
            draggedCard = card;
            card.classList.add('dragging');
        });

        card.addEventListener('dragend', () => {
            card.classList.remove('dragging');
            draggedCard = null;
        });
    });

    dropZones.forEach(zone => {
        zone.addEventListener('dragover', (e) => {
            e.preventDefault();
            if (!zone.classList.contains('correct')) {
                zone.classList.add('drag-over');
            }
        });

        zone.addEventListener('dragleave', () => {
            zone.classList.remove('drag-over');
        });

        zone.addEventListener('drop', () => {
            zone.classList.remove('drag-over');
            if (!draggedCard) return;

            const cardType = draggedCard.classList.contains('type-cond') ? 'cond' : 'res';
            const zoneType = zone.getAttribute('data-type');
            const targetVal = zone.getAttribute('data-target');
            const draggedVal = draggedCard.getAttribute('data-val');

            if (cardType === zoneType) {
                if (targetVal === draggedVal) {
                    // 放置正确
                    zone.textContent = draggedVal;
                    zone.classList.add('correct');
                    draggedCard.style.visibility = 'hidden';
                    checkCompletion();
                } else {
                    // 放置错误，给出引导性提示
                    showErrorTip(draggedVal, targetVal);
                }
            } else {
                tipBox.innerHTML = `<strong>提示：</strong>条件卡片只能放入“条件槽”，结果卡片只能放入“结果槽”！`;
            }
        });
    });

    function showErrorTip(draggedVal, targetVal) {
        let testVal = "1";
        if (draggedVal.includes("2") || targetVal.includes("2")) {
            testVal = "2";
        }
        if (draggedVal.includes(">") || targetVal.includes(">")) {
            testVal = "3";
        }
        tipBox.innerHTML = `<strong>提示：</strong>位置不对哦！试着在右下角将参数 a 调节到 <strong>a = ${testVal}</strong>，观察图像交点个数。`;
    }

    function checkCompletion() {
        const allCorrect = Array.from(dropZones).every(zone => zone.classList.contains('correct'));
        if (allCorrect) {
            tipBox.innerHTML = `<span style="color: #10b981; font-weight: bold;">🎉 太棒了！你已成功构建了严谨的分类讨论决策树！</span>`;
            document.querySelectorAll('.correct').forEach(el => el.classList.add('pulse-success'));
            drawTreeLines(true);
        } else {
            drawTreeLines();
        }
    }

    // 重置按钮
    document.getElementById('btn-reset').addEventListener('click', () => {
        dropZones.forEach(zone => {
            zone.classList.remove('correct', 'pulse-success');
            zone.textContent = zone.getAttribute('data-type') === 'cond' ? '放入条件' : '放入结果';
        });
        cards.forEach(card => {
            card.style.visibility = 'visible';
        });
        tipBox.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" stroke-width="2"><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3m.08 4h.01"/></svg><span>提示：请将右侧的条件和结果卡片拖拽到左侧对应的决策树分支中。</span>`;
        drawTreeLines();
    });

    // 2. 绘制决策树连线
    const svg = document.getElementById('tree-svg');
    function drawTreeLines(highlightAll = false) {
        svg.innerHTML = '';
        const containerRect = document.getElementById('tree-container').getBoundingClientRect();

        const root = document.querySelector('.root-node').getBoundingClientRect();
        const conds = [
            document.getElementById('slot-cond-1'),
            document.getElementById('slot-cond-2'),
            document.getElementById('slot-cond-3')
        ];
        const ress = [
            document.getElementById('slot-res-1'),
            document.getElementById('slot-res-2'),
            document.getElementById('slot-res-3')
        ];

        const rootX = root.left + root.width / 2 - containerRect.left;
        const rootY = root.top + root.height - containerRect.top;

        // 绘制根到条件的线
        conds.forEach((cond, index) => {
            const condRect = cond.getBoundingClientRect();
            const condX = condRect.left + condRect.width / 2 - containerRect.left;
            const condY = condRect.top - containerRect.top;
            const isCorrect = cond.classList.contains('correct') || highlightAll;

            const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            const d = `M ${rootX} ${rootY} C ${rootX} ${(rootY + condY)/2}, ${condX} ${(rootY + condY)/2}, ${condX} ${condY}`;
            path.setAttribute('d', d);
            path.setAttribute('stroke', isCorrect ? '#10b981' : '#cbd5e1');
            path.setAttribute('stroke-width', isCorrect ? '3' : '2');
            path.setAttribute('fill', 'none');
            svg.appendChild(path);

            // 绘制条件到结果的线
            const res = ress[index];
            const resRect = res.getBoundingClientRect();
            const resX = resRect.left + resRect.width / 2 - containerRect.left;
            const resY = resRect.top - containerRect.top;
            const isResCorrect = (cond.classList.contains('correct') && res.classList.contains('correct')) || highlightAll;

            const path2 = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            const d2 = `M ${condX} ${condRect.top + condRect.height - containerRect.top} C ${condX} ${(condRect.top + condRect.height - containerRect.top + resY)/2}, ${resX} ${(condRect.top + condRect.height - containerRect.top + resY)/2}, ${resX} ${resY}`;
            path2.setAttribute('d', d2);
            path2.setAttribute('stroke', isResCorrect ? '#10b981' : '#cbd5e1');
            path2.setAttribute('stroke-width', isResCorrect ? '3' : '2');
            path2.setAttribute('fill', 'none');
            svg.appendChild(path2);
        });
    }

    // 窗口大小改变时重绘连线
    window.addEventListener('resize', () => drawTreeLines());
    setTimeout(drawTreeLines, 100); // 延迟确保DOM渲染完毕

    // 3. 右下角微型图像验证 Canvas
    const canvas = document.getElementById('verify-canvas');
    const ctx = canvas.getContext('2d');
    const slider = document.getElementById('param-a-slider');
    const sliderVal = document.getElementById('param-a-val');

    function resizeCanvas() {
        canvas.width = canvas.parentElement.clientWidth;
        canvas.height = canvas.parentElement.clientHeight;
        drawVerification();
    }
    window.addEventListener('resize', resizeCanvas);
    setTimeout(resizeCanvas, 100);

    slider.addEventListener('input', (e) => {
        const val = parseFloat(e.target.value).toFixed(1);
        sliderVal.textContent = val;
        drawVerification();
    });

    // 绘制验证图像：以 y = |x^2 - 2x| 与 y = a 的交点为例
    function drawVerification() {
        if (canvas.width === 0) return;
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const width = canvas.width;
        const height = canvas.height;
        const centerX = width / 2;
        const centerY = height * 0.75; // 坐标原点偏下
