    function resizeCanvas() {
        const rect = canvas.getBoundingClientRect();
        canvas.width = rect.width;
        canvas.height = rect.height;

        // 重新计算原点位置，使其居中偏下
        config.originX = canvas.width / 2;
        config.originY = canvas.height * 0.75; 
        config.scale = canvas.width / (config.maxX - config.minX);
