    // 坐标转换：数学坐标 -> 屏幕像素坐标
    function toScreen(x, y) {
        return {
            x: config.originX + x * config.scale,
            y: config.originY - y * config.scale
        };
    }

    // 坐标转换：屏幕像素坐标 -> 数学坐标
    function toMath(px, py) {
        return {
            x: (px - config.originX) / config.scale,
            y: (config.originY - py) / config.scale
        };
    }

    // 绘制网格和坐标轴
    function drawGrid() {
        ctx.strokeStyle = '#e2e8f0';
        ctx.lineWidth = 1;

        // 竖线
        for (let x = config.minX; x <= config.maxX; x++) {
            const p = toScreen(x, 0);
            ctx.beginPath();
            ctx.moveTo(p.x, 0);
            ctx.lineTo(p.x, canvas.height);
            ctx.stroke();

            // 刻度值
            if (x !== 0) {
                ctx.fillStyle = '#7f8c8d';
                ctx.font = '12px Arial';
                ctx.textAlign = 'center';
                ctx.fillText(x, p.x, config.originY + 15);
            }
        }

        // 横线
        for (let y = Math.floor(config.minY); y <= config.maxY; y++) {
            const p = toScreen(0, y);
            ctx.beginPath();
            ctx.moveTo(0, p.y);
            ctx.lineTo(canvas.width, p.y);
            ctx.stroke();

            // 刻度值
            if (y !== 0) {
                ctx.fillStyle = '#7f8c8d';
                ctx.font = '12px Arial';
                ctx.textAlign = 'right';
                ctx.fillText(y, config.originX - 8, p.y + 4);
            }
        }

        // 绘制坐标轴
        ctx.strokeStyle = '#2c3e50';
        ctx.lineWidth = 2;

        // X轴
        ctx.beginPath();
        ctx.moveTo(0, config.originY);
        ctx.lineTo(canvas.width, config.originY);
        ctx.stroke();

        // Y轴
        ctx.beginPath();
        ctx.moveTo(config.originX, 0);
        ctx.lineTo(config.originX, canvas.height);
        ctx.stroke();

        // 轴箭头与标签
        ctx.fillStyle = '#2c3e50';
        ctx.font = 'bold 14px Arial';
        ctx.fillText('x', canvas.width - 15, config.originY - 10);
        ctx.fillText('y', config.originX + 10, 15);
        ctx.fillText('O', config.originX - 15, config.originY + 15);
    }

    // 绘制红色折线 y = |x-1| + |x+1|
    function drawTargetFunction() {
        ctx.strokeStyle = '#e74c3c';
        ctx.lineWidth = 3.5;
        ctx.beginPath();

        // 采样绘制折线
        const step = 0.1;
        let first = true;
        for (let x = config.minX; x <= config.maxX; x += step) {
            const y = Math.abs(x - 1) + Math.abs(x + 1);
            const p = toScreen(x, y);
            if (first) {
                ctx.moveTo(p.x, p.y);
                first = false;
            } else {
                ctx.lineTo(p.x, p.y);
            }
        }
        ctx.stroke();

        // 标注拐点
        const p1 = toScreen(-1, 2);
        const p2 = toScreen(1, 2);

        ctx.fillStyle = '#c0392b';
        ctx.beginPath();
        ctx.arc(p1.x, p1.y, 5, 0, Math.PI * 2);
        ctx.arc(p2.x, p2.y, 5, 0, Math.PI * 2);
        ctx.fill();

        ctx.font = '12px Arial';
        ctx.fillText('(-1, 2)', p1.x - 45, p1.y - 10);
        ctx.fillText('(1, 2)', p2.x + 10, p2.y - 10);
    }

    // 绘制动态蓝色斜线 y = x + b
    function drawDynamicLine(b) {
        ctx.strokeStyle = '#3498db';
        ctx.lineWidth = 3;

        const x1 = config.minX;
        const y1 = x1 + b;
        const x2 = config.maxX;
        const y2 = x2 + b;

        const p1 = toScreen(x1, y1);
        const p2 = toScreen(x2, y2);

        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.stroke();

        // 标注方程
        ctx.fillStyle = '#2980b9';
        ctx.font = 'italic bold 14px Arial';
        const labelPos = toScreen(2.5, 2.5 + b);
        ctx.fillText(`y = x + ${b.toFixed(2)}`, labelPos.x + 10, labelPos.y - 10);
    }

    // 计算并绘制交点
    function handleIntersections(b) {
        // y = |x-1| + |x+1| 的分段函数：
        // x < -1: y = -2x
        // -1 <= x <= 1: y = 2
        // x > 1: y = 2x

        // 与 y = x + b 的交点计算：
        // 1. x < -1 区域：-2x = x + b => 3x = -b => x = -b/3. 
        //    条件：-b/3 < -1 => b > 3
        // 2. -1 <= x <= 1 区域：2 = x + b => x = 2 - b.
        //    条件：-1 <= 2 - b <= 1 => 1 <= b <= 3
        // 3. x > 1 区域：2x = x + b => x = b.
        //    条件：b > 1

        let intersections = [];

        // 区域 1 交点
        if (b > 3) {
            const x = -b / 3;
            intersections.push({x: x, y: x + b});
        }
        // 区域 2 交点
        if (b >= 1 && b <= 3) {
            const x = 2 - b;
            intersections.push({x: x, y: x + b});
        }
        // 区域 3 交点
        if (b > 1) {
            const x = b;
            intersections.push({x: x, y: x + b});
        }

        // 绘制交点与闪烁效果
        intersections.forEach(pt => {
            const p = toScreen(pt.x, pt.y);

            // 闪烁外圈
            ctx.strokeStyle = 'rgba(231, 76, 60, ' + (0.4 + 0.4 * Math.sin(pulseTime)) + ')';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.arc(p.x, p.y, 10 + 4 * Math.sin(pulseTime), 0, Math.PI * 2);
            ctx.stroke();

            // 实心内圆
            ctx.fillStyle = '#e74c3c';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 6, 0, Math.PI * 2);
            ctx.fill();

            // 坐标标注
            ctx.fillStyle = '#333';
            ctx.font = 'bold 12px Arial';
            ctx.fillText(`(${pt.x.toFixed(2)}, ${pt.y.toFixed(2)})`, p.x + 12, p.y + 5);
        });

        return intersections.length;
    }

    // 绘制拐点金色光环
    function drawGoldenRing(b) {
        // 当且仅当直线经过拐点 (1, 2) 时，即 2 = 1 + b => b = 1
        if (Math.abs(b - 1) < 0.02) {
            const p = toScreen(1, 2);
            ctx.strokeStyle = '#f1c40f';
            ctx.lineWidth = 4;
            ctx.beginPath();
            ctx.arc(p.x, p.y, 15 + 5 * Math.sin(pulseTime * 2), 0, Math.PI * 2);
            ctx.stroke();

            ctx.fillStyle = 'rgba(241, 196, 15, 0.2)';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 15 + 5 * Math.sin(pulseTime * 2), 0, Math.PI * 2);
            ctx.fill();
        }
    }

    // 更新右侧面板状态描述
    function updateFeedback(b, count) {
        bValueDisplay.textContent = `b = ${b.toFixed(2)}`;

        // 临界状态 b = 1
        if (Math.abs(b - 1) < 0.02) {
            feedbackPanel.className = "feedback-panel critical-active";
            feedbackTitle.innerHTML = "🌟 临界状态 b = 1";
            feedbackText.innerHTML = `直线恰好经过拐点 <span class="highlight-text">(1, 2)</span>。<br>此时交点个数从 <span class="highlight-text">0个</span> 突变为 <span class="highlight-text">1个</span>，若 b 继续增大，交点将变为 <span class="highlight-text">2个</span>。`;
        } 
        // 临界状态 b = 3
        else if (Math.abs(b - 3) < 0.02) {
            feedbackPanel.className = "feedback-panel critical-active";
            feedbackTitle.innerHTML = "🌟 临界状态 b = 3";
            feedbackText.innerHTML = `直线恰好经过拐点 <span class="highlight-text">(-1, 2)</span>。<br>此时交点个数仍为 <span class="highlight-text">2个</span>，但交点的分布区域和计算规则发生变化。`;
        }
        // 普通状态
        else {
            feedbackPanel.className = "feedback-panel";
            feedbackTitle.innerHTML = "💡 当前状态观察";
            if (b < 1) {
                feedbackText.innerHTML = `当前 <span class="highlight-text">b < 1</span>。<br>直线在下方，与折线<span class="highlight-text">没有交点</span>（0个交点）。方程无实数根。`;
            } else if (b > 1 && b < 3) {
                feedbackText.innerHTML = `当前 <span class="highlight-text">1 < b < 3</span>。<br>直线与折线有 <span class="highlight-text">2个交点</span>。一个在底部水平段，一个在右侧斜段。`;
            } else if (b > 3) {
                feedbackText.innerHTML = `当前 <span class="highlight-text">b > 3</span>。<br>直线与折线有 <span class="highlight-text">2个交点</span>。分别在左侧斜段和右侧斜段。`;
            }
        }
    }

    // 渲染主循环
    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        const b = parseFloat(bSlider.value);

        drawGrid();
        drawTargetFunction();
        drawDynamicLine(b);
        drawGoldenRing(b);
        const count = handleIntersections(b);

        updateFeedback(b, count);

        pulseTime += 0.15;
        requestAnimationFrame(render);
    }

    // 初始化
    window.addEventListener('resize', resizeCanvas);

    // 启动
    resizeCanvas();
    render();
</script>

