<script>
    document.addEventListener('DOMContentLoaded', () => {
        const xInput = document.getElementById('x-input');
        const btnVerify = document.getElementById('btn-verify');
        const btnReset = document.getElementById('btn-reset');
        const calcDisplay = document.getElementById('calc-display');
        const xiaohuaAvatar = document.getElementById('xiaohua-avatar');
        const speechBubble = document.getElementById('speech-bubble');
        const overlapLine = document.getElementById('overlap-line');
        const interactivePoint = document.getElementById('interactive-point');
        const dynamicPointsGroup = document.getElementById('dynamic-points');
        const conclusionOverlay = document.getElementById('conclusion-overlay');
        const btnCloseOverlay = document.getElementById('btn-close-overlay');

        let verifiedCount = 0;

        // 验证逻辑
        btnVerify.addEventListener('click', () => {
            const xVal = parseFloat(xInput.value);

            if (isNaN(xVal)) {
                alert('请输入有效的数字！');
                return;
            }

            if (xVal < -1 || xVal > 1) {
                alert('为了推翻小华的“只有端点相碰”论断，请尝试输入区间 [-1, 1] 内的数进行探究！');
                return;
            }

            // 计算绝对值方程左边
            const term1 = Math.abs(xVal + 1);
            const term2 = Math.abs(xVal - 1);
            const sum = term1 + term2;

            // 渲染动态计算过程
            calcDisplay.innerHTML = `
                <div class="calc-step">
                    <span>代入 x = <span class="highlight-val">${xVal}</span> :</span>
                    <span>|${xVal} + 1| + |${xVal} - 1|</span>
                    <span>=</span>
                    <span>${term1.toFixed(3)} + ${term2.toFixed(3)}</span>
                    <span>=</span>
                    <span class="match-success">${sum.toFixed(1)}</span>
                    <span class="match-success" style="margin-left:10px;">( 恒等于 2 ! )</span>
                </div>
            `;

            // 更新几何图形中的交互点位置
            // 映射关系：x = -1 -> cx = 150, x = 1 -> cx = 350
            const cx = 150 + (xVal - (-1)) * 100;
            interactivePoint.setAttribute('cx', cx);
            interactivePoint.setAttribute('opacity', '1');

            // 增加一个微小的解点记录在图表上
            const newDot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            newDot.setAttribute('cx', cx);
            newDot.setAttribute('cy', '100');
            newDot.setAttribute('r', '4');
            newDot.setAttribute('fill', '#48bb78');
            dynamicPointsGroup.appendChild(newDot);

            verifiedCount++;

            // 触发认知冲突效果：小华气泡破裂，展示重合区间
            if (xVal > -1 && xVal < 1) {
                setTimeout(() => {
                    // 小华头像震惊
                    xiaohuaAvatar.textContent = '😱';
                    xiaohuaAvatar.style.transform = 'scale(1.2)';

                    // 气泡淡出
                    speechBubble.style.transition = 'all 0.5s';
                    speechBubble.style.opacity = '0.3';

                    // 亮起重合绿线
                    overlapLine.setAttribute('opacity', '1');

                    // 弹出最终冲突突破结论
                    if (verifiedCount >= 1) {
                        setTimeout(() => {
                            conclusionOverlay.classList.add('show');
                        }, 1200);
                    }
                }, 800);
            }
        });

        // 关闭结论遮罩
        btnCloseOverlay.addEventListener('click', () => {
