    const width = 756;
    const height = 310;

    function mapX(x) {
        return 80 + (x / 10) * (width - 160);
    }
    function mapY(y) {
        return (height - 60) - (y / 9) * (height - 100);
    }

    // 绘制静态背景（数轴、刻度、定点）
    function drawStatic() {
        let html = '';

        // 绘制网格线(水平)
        for (let y = 0; y <= 8; y += 2) {
            const py = mapY(y);
            html += `<line x1="50" y1="${py}" x2="${width-50}" y2="${py}" stroke="#27272a" stroke-dasharray="4" stroke-width="1" />`;
            html += `<text x="35" y="${py+5}" fill="#71717a" font-size="12" text-anchor="end">${y}</text>`;
        }

        // 绘制数轴 (y=0)
        const yZero = mapY(0);
        html += `<line x1="50" y1="${yZero}" x2="${width-50}" y2="${yZero}" stroke="#71717a" stroke-width="2" />`;
        // 数轴箭头
        html += `<polygon points="${width-50},${yZero-5} ${width-40},${yZero} ${width-50},${yZero+5}" fill="#71717a" />`;

        // 绘制刻度与数字
        for (let x = 1; x <= 9; x++) {
