            html += `<text x="${px}" y="${yZero+20}" fill="#a1a1aa" font-size="14" text-anchor="middle" font-family="sans-serif">${x}</text>`;
        }

        // 标注定点 3 和 7
        const x3 = mapX(3);
        const x7 = mapX(7);

        // 虚线投影
        html += `<line x1="${x3}" y1="${yZero}" x2="${x3}" y2="${mapY(4)}" stroke="#a1a1aa" stroke-dasharray="3" />`;
        html += `<line x1="${x7}" y1="${yZero}" x2="${x7}" y2="${mapY(4)}" stroke="#a1a1aa" stroke-dasharray="3" />`;

        // 定点圆点
        html += `<circle cx="${x3}" cy="${yZero}" r="6" fill="#fbbf24" />`;
        html += `<circle cx="${x7}" cy="${yZero}" r="6" fill="#fbbf24" />`;
        html += `<text x="${x3}" y="${yZero-12}" fill="#fbbf24" font-size="14" font-weight="bold" text-anchor="middle">A(3)</text>`;
        html += `<text x="${x7}" y="${yZero-12}" fill="#fbbf24" font-size="14" font-weight="bold" text-anchor="middle">B(7)</text>`;

        return html;
