    // 动态绘制折线与交点
    function updateVisualization() {
        const a = parseFloat(slider.value);
        aValueDisplay.textContent = a.toFixed(1);

        let html = drawStatic();

        // 1. 绘制折线 y = |x-3| + |x-7|
        // 关键折点：(0, 10), (3, 4), (7, 4), (10, 10)
        const p0 = {x: mapX(0), y: mapY(10)};
        const p1 = {x: mapX(3), y: mapY(4)};
        const p2 = {x: mapX(7), y: mapY(4)};
        const p3 = {x: mapX(10), y: mapY(10)};

        // 荧光绿色高亮区间 [3, 7] (当 a = 4 时)
        const isCritical = Math.abs(a - 4) < 0.05;
