        const polylineWidth = isCritical ? 4 : 3;
        const glowFilter = isCritical ? 'filter="drop-shadow(0px 0px 8px #4ade80)"' : '';

        html += `<path d="M ${p0.x} ${p0.y} L ${p1.x} ${p1.y} L ${p2.x} ${p2.y} L ${p3.x} ${p3.y}" 
                      fill="none" stroke="${polylineColor}" stroke-width="${polylineWidth}" ${glowFilter} />`;

        // 2. 绘制水平线 y = a
        const pyA = mapY(a);
        html += `<line x1="${mapX(0.5)}" y1="${pyA}" x2="${mapX(9.5)}" y2="${pyA}" stroke="#38bdf8" stroke-width="3" filter="drop-shadow(0px 0px 4px #38bdf8)" />`;
        html += `<text x="${mapX(9.5)+10}" y="${pyA+5}" fill="#38bdf8" font-size="16" font-weight="bold">y = ${a.toFixed(1)}</text>`;

        // 3. 计算并绘制交点
        if (a > 4) {
            // 两个交点
            // x1: 3 - (a-4)/2 = (10-a)/2
            // x2: 7 + (a-4)/2 = (10+a)/2
            const xVal1 = (10 - a) / 2;
            const xVal2 = (10 + a) / 2;
            const cx1 = mapX(xVal1);
            const cx2 = mapX(xVal2);

            html += `<circle cx="${cx1}" cy="${pyA}" r="6" fill="#ffffff" stroke="#38bdf8" stroke-width="2" />`;
            html += `<circle cx="${cx2}" cy="${pyA}" r="6" fill="#ffffff" stroke="#38bdf8" stroke-width="2" />`;

            // 投影到数轴
            html += `<line x1="${cx1}" y1="${pyA}" x2="${cx1}" y2="${mapY(0)}" stroke="#38bdf8" stroke-dasharray="2" />`;
            html += `<line x1="${cx2}" y1="${pyA}" x2="${cx2}" y2="${mapY(0)}" stroke="#38bdf8" stroke-dasharray="2" />`;

            // 交点坐标文本
            html += `<text x="${cx1}" y="${pyA-12}" fill="#ffffff" font-size="12" text-anchor="middle">x₁=${xVal1.toFixed(2)}</text>`;
            html += `<text x="${cx2}" y="${pyA-12}" fill="#ffffff" font-size="12" text-anchor="middle">x₂=${xVal2.toFixed(2)}</text>`;
        } else if (isCritical) {
            // 临界状态：重合线段 [3, 7]
            html += `<line x1="${p1.x}" y1="${p1.y}" x2="${p2.x}" y2="${p2.y}" stroke="#4ade80" stroke-width="6" filter="drop-shadow(0px 0px 12px #4ade80)" />`;
            // 数轴上对应区间高亮
            html += `<line x1="${p1.x}" y1="${mapY(0)}" x2="${p2.x}" y2="${mapY(0)}" stroke="#4ade80" stroke-width="6" filter="drop-shadow(0px 0px 8px #4ade80)" />`;
        }

        svg.innerHTML = html;

        // 触发挑战弹窗
        if (isCritical) {
            setTimeout(() => {
                overlay.style.display = 'flex';
