                    slider.value = 4.1;
                    updateVisualization();
                    feedback.innerHTML = '';
                    optionBtns.forEach(b => b.className = 'option-btn');
                }, 3000);
            } else {
                this.classList.add('wrong');
                feedback.innerHTML = '❌ 仔细想想，端点 3 和 7 能取到吗？距离之和是否仍为 4？';
                feedback.style.color = '#f87171';
            }
        });
    });

    // 监听滑块
    slider.addEventListener('input', updateVisualization);

    // 初始化
    updateVisualization();
</script>

