    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const workspace = document.getElementById('workspace');
            const svgCanvas = document.getElementById('svg-canvas');
            const dragAnchors = document.querySelectorAll('.drag-anchor');
            const dropSlots = document.querySelectorAll('.drop-slot');
            const statusDot = document.getElementById('status-dot');
            const statusInfo = document.getElementById('status-info');
            const btnReset = document.getElementById('btn-reset');

            let activeAnchor = null;
            let tempLine = null;
            const connections = []; // 存储已建立的连接关系 { anchorId, slotId, lineElement }

            // 初始化 SVG 尺寸
            function resizeCanvas() {
                const rect = workspace.getBoundingClientRect();
                svgCanvas.setAttribute('width', rect.width);
                svgCanvas.setAttribute('height', rect.height);
                redrawConnections();
            }
            window.addEventListener('resize', resizeCanvas);
            setTimeout(resizeCanvas, 100);

            // 拖拽逻辑
            dragAnchors.forEach(anchor => {
                anchor.addEventListener('mousedown', startDrag);
                anchor.addEventListener('touchstart', startDrag, { passive: false });
            });

            function startDrag(e) {
                const anchor = e.currentTarget;
                if (anchor.classList.contains('connected')) return;

                e.preventDefault();
                activeAnchor = anchor;

                const touch = e.type === 'touchstart' ? e.touches[0] : e;
                const rect = workspace.getBoundingClientRect();
                const startX = touch.clientX - rect.left;
                const startY = touch.clientY - rect.top;

                // 创建临时虚线
                tempLine = document.createElementNS('http://www.w3.org/2000/svg', 'line');
                tempLine.setAttribute('class', 'temp-line');
                tempLine.setAttribute('x1', startX);
                tempLine.setAttribute('y1', startY);
                tempLine.setAttribute('x2', startX);
                tempLine.setAttribute('y2', startY);
                svgCanvas.appendChild(tempLine);

                document.addEventListener('mousemove', dragMove);
                document.addEventListener('touchmove', dragMove, { passive: false });
                document.addEventListener('mouseup', endDrag);
                document.addEventListener('touchend', endDrag);
            }

            function dragMove(e) {
                if (!activeAnchor || !tempLine) return;
                e.preventDefault();

                const touch = e.type === 'touchmove' ? e.touches[0] : e;
                const rect = workspace.getBoundingClientRect();
                const currentX = touch.clientX - rect.left;
                const currentY = touch.clientY - rect.top;

                // 获取起点（锚点圆心位置）
                const dot = activeAnchor.querySelector('.drag-dot');
                const dotRect = dot.getBoundingClientRect();
                const startX = (dotRect.left + dotRect.width / 2) - rect.left;
                const startY = (dotRect.top + dotRect.height / 2) - rect.top;

                tempLine.setAttribute('x1', startX);
                tempLine.setAttribute('y1', startY);
                tempLine.setAttribute('x2', currentX);
                tempLine.setAttribute('y2', currentY);

                // 碰撞检测：高亮悬停的槽位
                const targetSlot = getHoveredSlot(touch.clientX, touch.clientY);
                dropSlots.forEach(slot => {
                    if (slot === targetSlot && canConnect(activeAnchor, slot)) {
                        slot.classList.add('hover');
                    } else {
                        slot.classList.remove('hover');
                    }
                });
            }

            function endDrag(e) {
                if (!activeAnchor) return;

                document.removeEventListener('mousemove', dragMove);
                document.removeEventListener('touchmove', dragMove);
                document.removeEventListener('mouseup', endDrag);
                document.removeEventListener('touchend', endDrag);

                const touch = e.type === 'touchend' ? e.changedTouches[0] : e;
                const targetSlot = getHoveredSlot(touch.clientX, touch.clientY);

                if (targetSlot && canConnect(activeAnchor, targetSlot)) {
                    // 成功连接
                    connectAnchorToSlot(activeAnchor, targetSlot);
                }

                if (tempLine) {
                    tempLine.remove();
                    tempLine = null;
                }

                dropSlots.forEach(slot => slot.classList.remove('hover'));
                activeAnchor = null;
                checkCompletion();
            }

            // 辅助检测
            function getHoveredSlot(clientX, clientY) {
                let hovered = null;
                dropSlots.forEach(slot => {
                    const rect = slot.getBoundingClientRect();
                    if (clientX >= rect.left && clientX <= rect.right &&
                        clientY >= rect.top && clientY <= rect.bottom) {
                        hovered = slot;
                    }
                });
                return hovered;
            }

            function canConnect(anchor, slot) {
                // 类型必须匹配 (cond 匹配 cond, val 匹配 val)
                if (anchor.dataset.type !== slot.dataset.type) return false;
                // 槽位必须未被占用
                if (slot.classList.contains('filled')) return false;
                // 值必须正确对应
                return anchor.dataset.value === slot.dataset.expected;
            }

            function connectAnchorToSlot(anchor, slot) {
                anchor.classList.add('connected');
                slot.classList.add('filled');

                // 创建永久实线
                const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
                line.setAttribute('class', 'solid-line');
                svgCanvas.appendChild(line);

                connections.push({
                    anchorId: anchor.id,
                    slotId: slot.id,
                    lineElement: line
                });

                drawConnectionLine(anchor, slot, line);
            }

            function drawConnectionLine(anchor, slot, line) {
                const rect = workspace.getBoundingClientRect();
                const dot = anchor.querySelector('.drag-dot');
                const dotRect = dot.getBoundingClientRect();
                const slotRect = slot.getBoundingClientRect();

                const x1 = (dotRect.left + dotRect.width / 2) - rect.left;
                const y1 = (dotRect.top + dotRect.height / 2) - rect.top;
                const x2 = slotRect.left - rect.left; // 连线到槽位左侧边缘
                const y2 = (slotRect.top + slotRect.height / 2) - rect.top;

