<script>
    // 初始化变量
    const canvas = document.getElementById('functionCanvas');
    const ctx = canvas.getContext('2d');
    const container = document.getElementById('canvasContainer');

    let width, height;
    let scale = 40; // 像素/单位
    let originX, originY;

    // 交互状态
    let currentThreshold = 2;
    let isFixed = false;
    let hoverA = 2.5; // 默认鼠标悬停在 y=2.5 处展示冲突
    let isMouseInCanvas = false;

    // 调整画布大小
    function resizeCanvas() {
        width = container.clientWidth;
        height = container.clientHeight;
        canvas.width = width;
        canvas.height = height;
        originX = width / 2 - 20; // 稍微偏左
        originY = height / 2 + 80; // 稍微偏下，给上方留出空间
    }

    // 绘制函数图像
    function draw() {
        ctx.clearRect(0, 0, width, height);

        // 1. 绘制网格
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 1;
        const gridStep = scale;
        for (let x = originX % gridStep; x < width; x += gridStep) {
            ctx.beginPath();
            ctx.moveTo(x, 0);
            ctx.lineTo(x, height);
            ctx.stroke();
        }
        for (let y = originY % gridStep; y < height; y += gridStep) {
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(width, y);
            ctx.stroke();
        }

        // 2. 绘制坐标轴
        ctx.strokeStyle = '#475569';
        ctx.lineWidth = 2;
        // X轴
        ctx.beginPath();
        ctx.moveTo(0, originY);
        ctx.lineTo(width, originY);
        ctx.stroke();
        // Y轴
        ctx.beginPath();
        ctx.moveTo(originX, 0);
        ctx.lineTo(originX, height);
        ctx.stroke();

        // 轴刻度与标签
        ctx.fillStyle = '#94a3b8';
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        // X轴刻度
        for (let i = -5; i <= 5; i++) {
            if (i === 0) continue;
            let cx = originX + i * scale;
            ctx.fillText(i, cx, originY + 5);
            ctx.beginPath();
            ctx.moveTo(cx, originY);
            ctx.lineTo(cx, originY - 4);
            ctx.stroke();
        }
        // Y轴刻度
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        for (let i = -2; i <= 7; i++) {
            if (i === 0) continue;
            let cy = originY - i * scale;
            ctx.fillText(i, originX - 8, cy);
            ctx.beginPath();
            ctx.moveTo(originX, cy);
            ctx.lineTo(originX + 4, cy);
            ctx.stroke();
        }
        // 原点
        ctx.fillText('0', originX - 8, originY + 5);

        // 3. 绘制折线函数 y = |x-1| + |x+2|
        ctx.strokeStyle = '#f43f5e';
        ctx.lineWidth = 4;
        ctx.beginPath();

        // 分段绘制以保证折角完美
        const points = [
            {x: -5, y: Math.abs(-5-1) + Math.abs(-5+2)},
            {x: -2, y: Math.abs(-2-1) + Math.abs(-2+2)},
            {x: 1, y: Math.abs(1-1) + Math.abs(1+2)},
            {x: 5, y: Math.abs(5-1) + Math.abs(5+2)}
        ];

        points.forEach((p, index) => {
            let cx = originX + p.x * scale;
            let cy = originY - p.y * scale;
            if (index === 0) ctx.moveTo(cx, cy);
            else ctx.lineTo(cx, cy);
        });
        ctx.stroke();

        // 4. 绘制关键转折点高亮
        ctx.fillStyle = '#f43f5e';
        points.slice(1, 3).forEach(p => {
            let cx = originX + p.x * scale;
            let cy = originY - p.y * scale;
            ctx.beginPath();
            ctx.arc(cx, cy, 6, 0, Math.PI * 2);
            ctx.fill();
            // 标注坐标
            ctx.fillStyle = '#e2e8f0';
            ctx.font = 'bold 12px sans-serif';
            ctx.fillText(`(${p.x}, ${p.y})`, cx + 10, cy - 10);
            ctx.fillStyle = '#f43f5e';
        });

        // 5. 绘制谷底区间高亮 (x在 -2 到 1 之间，y=3)
        ctx.strokeStyle = '#38bdf8';
        ctx.lineWidth = 2;
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(originX - 2 * scale, originY - 3 * scale);
        ctx.lineTo(originX + 1 * scale, originY - 3 * scale);
        ctx.stroke();
        ctx.setLineDash([]);

        // 6. 绘制动态扫描线 y = a
        let ay = originY - hoverA * scale;
        ctx.strokeStyle = '#38bdf8';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, ay);
        ctx.lineTo(width, ay);
        ctx.stroke();

        // 绘制交点
        let intersections = [];
        if (hoverA > 3) {
            // 两个交点
            // x > 1: 2x + 1 = a => x = (a-1)/2
            // x < -2: -2x - 1 = a => x = -(a+1)/2
            intersections.push((hoverA - 1) / 2);
            intersections.push(-(hoverA + 1) / 2);
        } else if (hoverA === 3) {
            // 无数个交点（线段）
            intersections.push(-2, 1);
        }

        ctx.fillStyle = '#38bdf8';
        intersections.forEach(ix => {
            let cx = originX + ix * scale;
            ctx.beginPath();
            ctx.arc(cx, ay, 6, 0, Math.PI * 2);
            ctx.fill();
        });

        // 绘制 y = a 标签
        ctx.fillStyle = '#38bdf8';
        ctx.font = 'bold 14px sans-serif';
        ctx.textAlign = 'left';
        ctx.fillText(` y = a (a = ${hoverA.toFixed(1)})`, 15, ay - 10);

        // 绘制交点个数提示
        let infoText = "";
        if (hoverA < 3) infoText = "无交点 (无解)";
        else if (hoverA === 3) infoText = "无数个交点 (有解)";
        else infoText = "2个交点 (有解)";
