            const btnConfirm = document.getElementById('btn-confirm');
            const formulaContainer = document.getElementById('formula-container');

            // 记录学生是否点击过各区间
            const clickedRanges = {
                '0': false,
                '1': false,
                '2': false
            };

            // 区域交互逻辑
            regions.forEach(region => {
                region.addEventListener('mouseenter', (e) => {
                    highlightRegion(region);
                });

                region.addEventListener('mouseleave', () => {
                    resetHighlight();
                });

                region.addEventListener('click', () => {
                    const index = region.getAttribute('data-index');
                    const rangeText = region.getAttribute('data-range');
                    const color = region.getAttribute('data-color');

                    // 标记已探索
                    clickedRanges[index] = true;

                    // 更新对应的大括号占位框
                    const box = document.getElementById(`box-${index}`);
                    box.textContent = rangeText;
                    box.classList.add('filled');
                    box.style.borderColor = color;
                    box.style.backgroundColor = '#ffffff';

                    // 视觉激活动效
                    regions.forEach(r => r.classList.remove('active'));
                    region.classList.add('active');

                    // 触发边界点高亮
                    updateBoundaryPoints(index);
                });
            });

            function highlightRegion(region) {
                const rangeText = region.getAttribute('data-range');
                const color = region.getAttribute('data-color');
                const index = region.getAttribute('data-index');

                // 计算气泡位置
                let targetX = 0;
                if (index === '0') targetX = 160;
                else if (index === '1') targetX = 370;
                else if (index === '2') targetX = 580;

                // 更新气泡
                tooltipBg.setAttribute('x', targetX - 60);
                tooltipBg.setAttribute('fill', color);
                tooltipBg.classList.add('tooltip-visible');

                tooltipTxt.setAttribute('x', targetX);
                tooltipTxt.textContent = rangeText;
                tooltipTxt.classList.add('tooltip-visible');
            }

            function resetHighlight() {
                tooltipBg.classList.remove('tooltip-visible');
                tooltipTxt.classList.remove('tooltip-visible');
            }

            function updateBoundaryPoints(activeIndex) {
                const ptLeft = document.getElementById('point-left');
                const ptRight = document.getElementById('point-right');

                ptLeft.classList.remove('active');
                ptRight.classList.remove('active');

                if (activeIndex === '0') {
                    ptLeft.classList.add('active');
                } else if (activeIndex === '1') {
                    ptLeft.classList.add('active');
                    ptRight.classList.add('active');
                } else if (activeIndex === '2') {
                    ptRight.classList.add('active');
                }
            }

            // 确认划分按钮 - 展现分段函数雏形
            btnConfirm.addEventListener('click', () => {
                formulaContainer.classList.add('visible');

                // 自动填充未点击的区间，帮助教学收尾
                regions.forEach(region => {
                    const index = region.getAttribute('data-index');
                    if (!clickedRanges[index]) {
                        const rangeText = region.getAttribute('data-range');
                        const color = region.getAttribute('data-color');
                        const box = document.getElementById(`box-${index}`);

