                            box.textContent = rangeText;
                            box.classList.add('filled');
                            box.style.borderColor = color;
                            box.style.transform = 'scale(1.05)';
                            setTimeout(() => box.style.transform = 'scale(1)', 200);
                        }, index * 200);
                    }
                });
            });
        });
    </script>
