    <script>
        const container = document.getElementById('interactive-container');
        const svg = document.getElementById('svg-canvas');
        const cards = document.querySelectorAll('.card');
        const successBanner = document.getElementById('success-banner');
        const statusTip = document.getElementById('status-tip');
        const btnReset = document.getElementById('btn-reset');

        let selectedLeft = null;
        let connections = []; // 存储格式：{ leftId, rightId, isCorrect }

        // 正确的映射关系
        const correctPairs = {
            'card-1': 'card-q',    // 1 是较大值，对应 q (p < q)
            'card-neg1': 'card-p'  // -1 是较小值，对应 p
        };

        // 初始化与窗口自适应
        function resizeCanvas() {
            svg.setAttribute('width', container.clientWidth);
            svg.setAttribute('height', container.clientHeight);
            drawLines();
        }
        window.addEventListener('resize', resizeCanvas);
        setTimeout(resizeCanvas, 100);

        // 卡片点击事件
        cards.forEach(card => {
            card.addEventListener('click', () => {
                if (card.classList.contains('matched')) return;

                const side = card.dataset.side;

                if (side === 'left') {
                    // 切换左侧选择
                    document.querySelectorAll('.left-column .card').forEach(c => c.classList.remove('selected'));
                    card.classList.add('selected');
                    selectedLeft = card;
                    statusTip.innerHTML = "💡 请选择右侧与 <b>" + card.querySelector('.card-value').innerText + "</b> 对应的字母。";
                } else if (side === 'right' && selectedLeft) {
                    // 尝试连接
                    const leftId = selectedLeft.id;
                    const rightId = card.id;

                    // 检查是否已经有连接占用了这两个卡片，如果有则清除旧连接
                    connections = connections.filter(conn => conn.leftId !== leftId && conn.rightId !== rightId);

                    const isCorrect = correctPairs[leftId] === rightId;
                    connections.push({ leftId, rightId, isCorrect });

                    // 清除左侧选择状态
                    selectedLeft.classList.remove('selected');
                    selectedLeft = null;

                    // 检查是否全部正确配对
                    checkGameStatus();
                    drawLines();
                }
            });
        });

        // 绘制连线
        function drawLines() {
            // 清空旧线
            svg.innerHTML = '';

            connections.forEach(conn => {
                const leftCard = document.getElementById(conn.leftId);
                const rightCard = document.getElementById(conn.rightId);

                const leftRect = leftCard.getBoundingClientRect();
                const rightRect = rightCard.getBoundingClientRect();
                const containerRect = container.getBoundingClientRect();

                // 计算相对于 SVG 容器的坐标
                const x1 = leftRect.right - containerRect.left;
                const y1 = leftRect.top + leftRect.height / 2 - containerRect.top;
                const x2 = rightRect.left - containerRect.left;
                const y2 = rightRect.top + rightRect.height / 2 - containerRect.top;

                // 创建贝塞尔曲线，让连线更平滑美观
                const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
                const controlOffset = Math.abs(x2 - x1) * 0.5;
                const d = `M ${x1} ${y1} C ${x1 + controlOffset} ${y1}, ${x2 - controlOffset} ${y2}, ${x2} ${y2}`;

                path.setAttribute('d', d);
                path.setAttribute('fill', 'none');

                if (conn.isCorrect && connections.length === 2) {
                    path.setAttribute('stroke', '#16a34a'); // 成功绿色
                    path.setAttribute('stroke-width', '4');
                } else {
                    path.setAttribute('stroke', '#2563eb'); // 过程蓝色
                    path.setAttribute('stroke-width', '3');
                }

                svg.appendChild(path);
            });
        }

        // 检查游戏状态
        function checkGameStatus() {
            if (connections.length === 2) {
                const allCorrect = connections.every(conn => conn.isCorrect);
                if (allCorrect) {
                    // 全部正确
                    cards.forEach(c => c.classList.add('matched'));
                    successBanner.classList.add('show');
                    statusTip.innerHTML = "✨ 完美配对！你已经看透了字母的本质。";
                } else {
                    statusTip.innerHTML = "❌ 对应关系好像不对哦，再观察一下大小关系？点击“重置”重新试试。";
                }
            } else {
                statusTip.innerHTML = "💡 已建立一条连线，请继续配对其余卡片。";
            }
        }

        // 重置
        btnReset.addEventListener('click', () => {
            connections = [];
            selectedLeft = null;
            cards.forEach(c => {
                c.classList.remove('selected', 'matched');
            });
            successBanner.classList.remove('show');
            statusTip.innerHTML = "💡 提示：点击左侧卡片，再点击右侧对应的字母卡片进行连线。";
            drawLines();
        });
    </script>
</body>
