<script>
    // 常量定义
    const SVG_WIDTH = 700;
    const AXIS_LEFT = 80;
    const AXIS_RIGHT = 620;
    const AXIS_Y = 80;
    const VAL_MIN = -5;
    const VAL_MAX = 5;
    const MIN_DISTANCE = 0.5; // 限制 p 和 q 的最小间距，防止重合

    // 状态变量 (初始值 p = -1, q = 1)
    let valP = -1.0;
    let valQ = 1.0;

    // 获取 DOM 元素
    const svg = document.getElementById('axisSvg');
    const ticksGroup = document.getElementById('ticks-group');
    const grpP = document.getElementById('grp-p');
    const grpQ = document.getElementById('grp-q');
    const lblP = document.getElementById('lbl-p');
    const lblQ = document.getElementById('lbl-q');
    const distBracket = document.getElementById('distance-bracket');
    const distText = document.getElementById('distance-text');

    const formulaP = document.getElementById('formula-p');
    const formulaQ = document.getElementById('formula-q');
    const formulaDist = document.getElementById('formula-dist');

    // 预设按钮
    const btn1 = document.getElementById('btn-preset-1');
    const btn2 = document.getElementById('btn-preset-2');
    const btn3 = document.getElementById('btn-preset-3');
    const btn4 = document.getElementById('btn-preset-4');

    // 坐标转换：数值 -> SVG X 坐标
    function valToX(val) {
        const ratio = (val - VAL_MIN) / (VAL_MAX - VAL_MIN);
        return AXIS_LEFT + ratio * (AXIS_RIGHT - AXIS_LEFT);
    }

    // 坐标转换：SVG X 坐标 -> 数值
    function xToVal(x) {
        const ratio = (x - AXIS_LEFT) / (AXIS_RIGHT - AXIS_LEFT);
        const val = VAL_MIN + ratio * (VAL_MAX - VAL_MIN);
        return Math.max(VAL_MIN, Math.min(VAL_MAX, val));
    }

    // 初始化数轴刻度
    function drawTicks() {
        ticksGroup.innerHTML = '';
        for (let v = VAL_MIN; v <= VAL_MAX; v += 1) {
            const x = valToX(v);
            // 刻度线
            const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
            line.setAttribute('x1', x);
            line.setAttribute('y1', AXIS_Y - 5);
            line.setAttribute('x2', x);
            line.setAttribute('y2', AXIS_Y + 5);
            line.setAttribute('class', 'tick-line');

            // 刻度值
            const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
            text.setAttribute('x', x);
            text.setAttribute('y', AXIS_Y + 22);
            text.setAttribute('class', 'tick-text');
            text.textContent = v;

            ticksGroup.appendChild(line);
            ticksGroup.appendChild(text);
        }
    }

    // 更新视图
    function updateView() {
        const xP = valToX(valP);
        const xQ = valToX(valQ);

        // 更新点 p 位置与标签
        grpP.setAttribute('transform', `translate(${xP - 200}, 0)`); // 基于初始200偏移
        lblP.textContent = `p (${valP.toFixed(1)})`;

        // 更新点 q 位置与标签
        grpQ.setAttribute('transform', `translate(${xQ - 400}, 0)`); // 基于初始400偏移
        lblQ.textContent = `q (${valQ.toFixed(1)})`;

        // 更新距离括号与文本
        const bracketY = 50;
        const bracketHeight = 10;
        distBracket.setAttribute('d', `M ${xP},${bracketY + bracketHeight} L ${xP},${bracketY} L ${xQ},${bracketY} L ${xQ},${bracketY + bracketHeight}`);

        const midX = (xP + xQ) / 2;
        distText.setAttribute('x', midX);
        const distance = valQ - valP;
        distText.textContent = `距离 = ${distance.toFixed(1)}`;

        // 更新公式面板
        formulaP.textContent = valP.toFixed(1);
        formulaQ.textContent = valQ.toFixed(1);
        formulaDist.textContent = distance.toFixed(1);

        // 激活对应的预设高亮
        updatePresetButtonHighlight();
    }

    // 拖拽交互逻辑
    let activeDragNode = null;

    function getEventX(e) {
        if (e.touches && e.touches.length) {
            return e.touches[0].clientX;
        }
        return e.clientX;
    }

    function handleStart(node, e) {
        activeDragNode = node;
        e.preventDefault();
    }

    function handleMove(e) {
        if (!activeDragNode) return;

        const rect = svg.getBoundingClientRect();
        const clientX = getEventX(e);
        // 转换为 SVG 内部坐标系
        const svgX = ((clientX - rect.left) / rect.width) * SVG_WIDTH;
        let val = xToVal(svgX);

        // 精度保留一位小数，使拖拽更平滑且数值整洁
        val = Math.round(val * 10) / 10;

        if (activeDragNode === 'p') {
            // p 不能超过 q - 最小间距
            if (val > valQ - MIN_DISTANCE) {
                val = valQ - MIN_DISTANCE;
            }
            valP = val;
        } else if (activeDragNode === 'q') {
            // q 不能小于 p + 最小间距
            if (val < valP + MIN_DISTANCE) {
                val = valP + MIN_DISTANCE;
            }
            valQ = val;
        }

        updateView();
    }

    function handleEnd() {
        activeDragNode = null;
    }

    // 绑定拖拽事件
    grpP.addEventListener('mousedown', (e) => handleStart('p', e));
    grpP.addEventListener('touchstart', (e) => handleStart('p', e));

    grpQ.addEventListener('mousedown', (e) => handleStart('q', e));
    grpQ.addEventListener('touchstart', (e) => handleStart('q', e));

    window.addEventListener('mousemove', handleMove);
    window.addEventListener('touchmove', handleMove, { passive: false });

    window.addEventListener('mouseup', handleEnd);
    window.addEventListener('touchend', handleEnd);

    // 预设切换逻辑
    function setPreset(p, q) {
        valP = p;
        valQ = q;
        updateView();
    }

    function updatePresetButtonHighlight() {
        btn1.classList.remove('btn-active');
        btn2.classList.remove('btn-active');
        btn3.classList.remove('btn-active');
        btn4.classList.remove('btn-active');

        if (valP === -1.0 && valQ === 1.0) btn1.classList.add('btn-active');
        else if (valP === 1.5 && valQ === 4.5) btn2.classList.add('btn-active');
        else if (valP === -4.5 && valQ === -1.5) btn3.classList.add('btn-active');
        else if (valP === -3.0 && valQ === 2.0) btn4.classList.add('btn-active');
    }

    btn1.addEventListener('click', () => setPreset(-1.0, 1.0));
    btn2.addEventListener('click', () => setPreset(1.5, 4.5));
    btn3.addEventListener('click', () => setPreset(-4.5, -1.5));
    btn4.addEventListener('click', () => setPreset(-3.0, 2.0));

    // 初始化运行
    drawTicks();
    setPreset(-1.0, 1.0); // 默认经典场景
</script>

</body>
